  const kern = { 'Ubuntu 24.04 LTS': '6.8.0-45-generic', 'Ubuntu 22.04 LTS': '5.15.0-122-generic', 'Debian 12': '6.1.0-25-amd64', 'Debian 11': '5.10.0-32-amd64' }[sv.os] || '6.8.0-45-generic';
